import{_ as o,o as t,c as d,a2 as a}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"搜尋語法","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/search-syntax.md","filePath":"zh-HK/user-guide/search-syntax.md","lastUpdated":1786770456000}'),c={name:"zh-HK/user-guide/search-syntax.md"};function s(r,e,n,i,l,p){return t(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="搜尋語法" tabindex="-1">搜尋語法 <a class="header-anchor" href="#搜尋語法" aria-label="Permalink to &quot;搜尋語法&quot;">​</a></h1><p>Lertaro 的搜尋框支援的不只是普通輸入。下面每一種操作符都可以和普通模糊詞混合使用在同一條查詢裏。</p><h2 id="模糊匹配-預設" tabindex="-1">模糊匹配(預設) <a class="header-anchor" href="#模糊匹配-預設" aria-label="Permalink to &quot;模糊匹配(預設)&quot;">​</a></h2><p>輸入名稱的任意一部分即可命中，只要字元按順序出現在檔案/資料夾名的任意位置即可，不需要輸入連續的子串：</p><table tabindex="0"><thead><tr><th>輸入</th><th>命中</th></tr></thead><tbody><tr><td><code>swlst</code></td><td><code>Lertaro.exe</code></td></tr><tr><td><code>report</code></td><td><code>Q3-report-final.docx</code></td></tr></tbody></table><p>在<strong>設定 → 通用 → 系統 → 啓用模糊匹配</strong>裏關掉這個開關後，普通查詢詞(不帶任何操作符)就必須作為連續子串出現——<code>abc</code> 不再匹配 <code>a-b-c</code>。下面表格裏的每一種操作符不受這個開關影響，行為完全一樣；開關只改變普通詞本身的要求。<code>&#39;</code> 操作符不管這個開關開沒開，都會對單個詞翻轉精確性，所以你可以在一條整體走精確匹配的查詢裏塞進一個模糊詞，或者反過來，而不用去改這個全域開關。</p><h2 id="多個詞" tabindex="-1">多個詞 <a class="header-anchor" href="#多個詞" aria-label="Permalink to &quot;多個詞&quot;">​</a></h2><p>用空格分隔多個詞。每個詞都會進一步縮小結果範圍——但<strong>不要求</strong>這些詞按你輸入的順序出現：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report final</span></span></code></pre></div><p><code>final-Q3-report.docx</code> 和 <code>Q3-report-final.docx</code> 都能匹配。</p><h2 id="大小寫敏感" tabindex="-1">大小寫敏感 <a class="header-anchor" href="#大小寫敏感" aria-label="Permalink to &quot;大小寫敏感&quot;">​</a></h2><ul><li><strong>全部小寫</strong>的查詢不區分大小寫：<code>myfile</code> 可以匹配 <code>MyFile</code>、<code>MYFILE</code> 等。</li><li>只要查詢裏<strong>出現任意大寫字母</strong>，該詞就變為大小寫敏感：<code>MyFile</code> 只匹配 <code>MyFile</code>，不匹配 <code>myfile</code>。</li></ul><h2 id="操作符" tabindex="-1">操作符 <a class="header-anchor" href="#操作符" aria-label="Permalink to &quot;操作符&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前綴/後綴</th><th>示例</th><th>效果</th></tr></thead><tbody><tr><td>(無)</td><td><code>report</code></td><td>預設的模糊匹配，命中名稱中任意位置。</td></tr><tr><td><code>!</code></td><td><code>!temp</code></td><td><strong>排除</strong>——過濾掉名稱中含有 <code>temp</code> 這個精確子串的結果(這一項不走模糊匹配)。</td></tr><tr><td><code>&#39;</code></td><td><code>&#39;report</code></td><td>對這一個詞<strong>翻轉精確性</strong>——模糊匹配開啓(預設)時變成精確子串匹配；在設定裏關閉模糊匹配後，這個詞反而會變回模糊匹配。</td></tr><tr><td><code>&#39;...&#39;</code></td><td><code>&#39;final report&#39;</code></td><td>精確匹配，且要求詞邊界(不會命中被包在更長單詞內部的情況)。</td></tr><tr><td><code>^</code></td><td><code>^IMG</code></td><td><strong>前綴</strong>匹配——名稱必須以 <code>IMG</code> 開頭。</td></tr><tr><td><code>$</code></td><td><code>.pdf$</code></td><td><strong>後綴</strong>匹配——名稱必須以 <code>.pdf</code> 結尾。</td></tr><tr><td><code>^...$</code></td><td><code>^readme.md$</code></td><td><strong>完全相等</strong>——名稱必須正好是 <code>readme.md</code>。僅當兩者包住<strong>同一個</strong>詞時成立；分別寫在不同的詞上時，它們各自仍然只是前綴和後綴過濾。</td></tr><tr><td><code>|</code></td><td><code>report | summary</code></td><td><strong>或</strong>——匹配管道符任意一側。</td></tr></tbody></table><p>這些操作符可以自由組合，例如 <code>^IMG !.png$ 2024</code> 可以找到以 <code>IMG</code> 開頭、包含 2024、但<strong>不是</strong> PNG 的檔案。</p><p>&quot;或&quot;查詢裏，一個結果名稱中<strong>每一個</strong>真正匹配到的詞都會高亮，不只是最先匹配到的那一個——所以 <code>report | summary</code> 如果結果名稱裏同時包含這兩個詞，兩個詞都會被高亮。</p><h2 id="貼上多行文本" tabindex="-1">貼上多行文本 <a class="header-anchor" href="#貼上多行文本" aria-label="Permalink to &quot;貼上多行文本&quot;">​</a></h2><p>貼上包含多行的文本——比如從表格或文本檔案裏一行一個檔案名複製過來的內容——Lertaro 會自動把它們摺疊成一條 OR 查詢，而不是原樣貼上：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>123</span></span>
<span class="line"><span>456</span></span>
<span class="line"><span>678</span></span></code></pre></div><p>貼上進去會變成 <code>123 | 456 | 678</code>，同時匹配這三者中的任意一個。空行會被跳過。普通的單行貼上不受影響。</p><h2 id="指定盤符" tabindex="-1">指定盤符 <a class="header-anchor" href="#指定盤符" aria-label="Permalink to &quot;指定盤符&quot;">​</a></h2><p>在查詢開頭輸入盤符加冒號，即可把搜尋範圍限定在該盤，後面照常輸入關鍵詞：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d: report</span></span></code></pre></div><p>只在 <code>D:</code> 盤搜尋。</p><p>空格可以省略：<code>d:report</code> 和 <code>d: report</code> 意思相同。</p><h2 id="路徑模式" tabindex="-1">路徑模式 <a class="header-anchor" href="#路徑模式" aria-label="Permalink to &quot;路徑模式&quot;">​</a></h2><p>如果查詢裏包含路徑分隔符(<code>\\</code> 或 <code>/</code>)，Lertaro 會切換到路徑模式，按完整路徑而不僅僅是名稱來匹配——適合直接跳轉到已知的資料夾：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D:\\Projects\\Lertaro</span></span></code></pre></div><p>以分隔符結尾(<code>D:\\Projects\\</code>)則會搜尋該資料夾<strong>內部</strong>的內容。</p><h2 id="按資料夾名與通配符二次過濾-query-tokens" tabindex="-1">按資料夾名與通配符二次過濾 (Query Tokens) <a class="header-anchor" href="#按資料夾名與通配符二次過濾-query-tokens" aria-label="Permalink to &quot;按資料夾名與通配符二次過濾 (Query Tokens)&quot;">​</a></h2><p>Lertaro 支援在主搜尋關鍵字後面使用查詢標記（Query Tokens，預設通過前綴 <code>:</code> 或專用觸發前綴引用）對主檢索結果進行二次鏈式過濾：</p><ul><li><strong>通配符二次過濾（<code>:?&lt;通配符表達式&gt;</code> 或 <code>?&lt;通配符表達式&gt;</code>）</strong>：使用 Windows 標準通配符語法（<code>?</code> 匹配任意單字元，<code>*</code> 匹配任意多字元）對主搜尋結果進行二次精確定位。例如輸入 <code>mp4 :?(2026???????????)</code> 或 <code>mp4 ?(2026???????????)</code>，可精確檢索出名字中帶 2026 及 11 位日期時間戳的重複影片。支援用 <code>|</code> 或 <code>;</code> 分隔多個表達式組成 OR 條件（例如 <code>?(2026*)|*.png</code>）。</li><li><strong>路徑匹配（<code>::&lt;路徑表達式&gt;</code>）</strong>：要求結果名稱或上級資料夾匹配指定文字（如 <code>1080 ::wallpapers</code> 或 <code>report ::2024</code>）。</li><li><strong>自訂分類（<code>:@&lt;關鍵字&gt;</code>）</strong>：套用內置或自訂的副檔名過濾規則（如 <code>:@doc</code> 或 <code>:@video</code>）。</li></ul><h2 id="詞描述的是資料夾-不是檔案本身" tabindex="-1">詞描述的是資料夾，不是檔案本身 <a class="header-anchor" href="#詞描述的是資料夾-不是檔案本身" aria-label="Permalink to &quot;詞描述的是資料夾，不是檔案本身&quot;">​</a></h2><p>如果按檔案/資料夾名匹配未能填滿結果，Lertaro 會自動補上一批，額外允許詞命中上級資料夾——不需要任何特殊語法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d01j dcj</span></span></code></pre></div><p>即使 <code>dcj</code> 從未出現在檔案自己的名字裏，也能找到一個名為 <code>d01j</code>、位於名為(或別名為)<code>dcj</code> 的資料夾下的檔案。這只是用檔案上層的資料夾名，補齊查詢裏沒被檔案名本身涵蓋的部分——至少要有一個詞仍然命中檔案名本身，而且只在按名稱的普通搜尋未填滿結果時才會觸發；補上來的結果一律排在它們後面，不會與之混排，所以永遠不會頂掉或打亂普通搜尋本來就能找到的結果。上級資料夾的匹配方式和檔案名完全一樣，所以拼音在這裏同樣能命中中文資料夾名。</p><h2 id="單次搜尋繞過排除規則" tabindex="-1">單次搜尋繞過排除規則 <a class="header-anchor" href="#單次搜尋繞過排除規則" aria-label="Permalink to &quot;單次搜尋繞過排除規則&quot;">​</a></h2><p>在查詢開頭加 <code>*</code>，可以讓這一次搜尋繞過你自己設定的<a href="./settings/index-drives.html#排除規則">排除規則</a>—— <code>ExcludedPaths</code>、忽略的 glob、忽略的正則——而不需要改動設定本身：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*node_modules</span></span></code></pre></div><p><code>*</code> 本身會在匹配之前被剝離掉，不會被當成搜尋文字的一部分。這只能找回<strong>已經被索引過</strong>的結果；一個從未被索引過的資料夾(網絡盤或 WSL 上被排除的資料夾)依然不會出現。隱藏/系統檔案不受影響，始終照常過濾——<code>*</code> 只影響你自己配置的排除規則。只打 <code>*</code>、後面還沒打內容時，會顯示&quot;繼續輸入以搜尋&quot;這樣的提示，而不是&quot;無搜尋結果&quot;，因為這時候實際上還沒有真正搜尋過。</p><h2 id="結果類型觸發符" tabindex="-1">結果類型觸發符 <a class="header-anchor" href="#結果類型觸發符" aria-label="Permalink to &quot;結果類型觸發符&quot;">​</a></h2><p>可選功能，預設沒有配置，需要自己指定字元。如果你在<strong>設定 → 通用 → 快速搜尋視窗 → 結果類型優先級</strong>裏給某個結果類型配了觸發符，把這個字元打在快速視窗查詢的最前面，就只會顯示這個類型的結果——應用程式、系統設定、某一個具體的檔案過濾器、某個插件自己的條目，或者純檔案——其他類型全部隱藏：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>;vs</span></span></code></pre></div><p>如果 <code>;</code> 是應用程式這個類型配置的觸發符，這樣搜就只會在應用程式裏找&quot;Visual Studio&quot;，不管其他類型的文本本來匹配得多好都不參與競爭。只打觸發符、後面還沒打內容時，會顯示一個說明具體類型的提示，而不是&quot;無搜尋結果&quot;。在快速視窗和內嵌視窗中，歷史記錄和收藏夾不受影響——不管有沒有觸發符，它們始終排最前；完整視窗不會把這些回憶項目加入結果。預設沒有配置任何觸發符，去<a href="./settings/general.html#快速搜尋視窗">通用設定</a>裏可以自行設定。</p><h2 id="中文檔案名-拼音別名" tabindex="-1">中文檔案名:拼音別名 <a class="header-anchor" href="#中文檔案名-拼音別名" aria-label="Permalink to &quot;中文檔案名:拼音別名&quot;">​</a></h2><p>包含中文字元的檔案名會自動支援拼音搜尋，無需任何配置：</p><ul><li><strong>全拼</strong>:輸入 <code>chongqing</code> 可以匹配名為&quot;重慶&quot;的檔案。</li><li><strong>首字母</strong>:輸入 <code>cq</code> 同樣可以匹配&quot;重慶&quot;(每個音節的首字母)。</li><li><strong>多音字</strong>(有多種讀音的漢字)會為每種常見讀音都生成別名，所以不管你想到的是哪種讀音，通常都能命中。</li></ul><p>這是由內置的別名插件負責實現的——如果想確認它是否啓用，可以到<strong>設定 → 插件</strong>裏查看。</p><h2 id="西班牙語檔案名-重音別名" tabindex="-1">西班牙語檔案名：重音別名 <a class="header-anchor" href="#西班牙語檔案名-重音別名" aria-label="Permalink to &quot;西班牙語檔案名：重音別名&quot;">​</a></h2><p>包含西班牙語重音字元（<code>á</code>、<code>é</code>、<code>í</code>、<code>ó</code>、<code>ú</code>、<code>ü</code>、<code>ñ</code>）的檔案名可自動透過標準無重音 ASCII 字母進行搜尋，無需額外設定：輸入 <code>cancion</code> 可比對 <code>Canción.mp3</code>，輸入 <code>nino</code> 可比對 <code>Niño.txt</code>，輸入 <code>ciguena</code> 可比對 <code>Cigüeña.png</code>。比對的字元（包含原檔案名中的重音字元）將保持精準高亮。該功能由內置的 <code>SpanishAlias</code> 插件提供，可在 <strong>設定 → 插件</strong> 中檢視與管理。</p><h2 id="收藏夾-而非自訂別名" tabindex="-1">收藏夾，而非自訂別名 <a class="header-anchor" href="#收藏夾-而非自訂別名" aria-label="Permalink to &quot;收藏夾，而非自訂別名&quot;">​</a></h2><p>Lertaro 沒有一個通用的&quot;自訂別名/宏&quot;系統。最接近的等價功能是<a href="./settings/favorites.html">收藏夾</a>：把資料夾、檔案或網址收藏為一個自訂顯示名，之後就能用這個名字搜到它(結果裏會帶 ★ 標記)。如果你想要的其實是&quot;自訂一個關鍵詞來啓動某個程式&quot;，可以看看<a href="./instant-answers.html#自訂命令">自訂命令</a>。</p>`,52)])])}const g=o(c,[["render",s]]);export{u as __pageData,g as default};
